import{_ as n,l as s,o as e,c as o,v as t,p as l,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"图流与半流算法","description":"","frontmatter":{"title":"图流与半流算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/graph-streaming.md","filePath":"cs/graph-streaming.md","lastUpdated":1789023840000}'),c={name:"cs/graph-streaming.md"};function m(u,a,_,E,B,f){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="图流与半流算法" tabindex="-1">图流与半流算法 <a class="header-anchor" href="#图流与半流算法" aria-label="Permalink to &quot;图流与半流算法&quot;">​</a></h1><div class="epigraph"><p>边以流的形式到达，内存远小于 $n$：连通、匹配、最短路都要抽样、素描或多遍；半流允许来回扫存储。</p><footer>—— 据 Muthukrishnan, Data Streams: Algorithms and Applications, 2005；Feigenbaum 等图流早期工作整理</footer></div><p>上一课<a href="/cs/dynamic-connectivity">动态连通性</a>假定图在内存里改边。图流：边序列一次或少数次经过，空间 \\(O(n\\,\\mathrm{polylog}\\,n)\\) 或更小。不重写 Holm 的森林。缺口是流模型下还能回答什么：连通性素描、生成树的障碍、匹配的近似。本单元「最短路与动态图」在此结束；下一单元数值与代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>插入流：边只加。动态流：边可删（更难）。半流（semi-streaming）：空间 \\(\\tilde O(n)\\)，可存生成树级别。已知：半流可维护生成树（插边）；匹配有常数近似；最短路精确一般不行。更小空间要 sketch（连通分量的线性素描）。</p><p>缺口是空间预算，不是 CH。不要声称流上线性时间精确最大流——模型不允许邻接表随机访问。</p><h3 id="一遍过不等于在线算法" tabindex="-1">一遍过不等于在线算法 <a class="header-anchor" href="#一遍过不等于在线算法" aria-label="Permalink to &quot;一遍过不等于在线算法&quot;">​</a></h3><p>在线算法对不可撤回决策比竞争比；流算法可事后输出，只是内存小。后课竞争比另开。本课内存。</p><p><span class="marginnote">Muthukrishnan 2005 综述流。图流半流成为标准分层。 Ahn–Guha–McGregor 线性素描做连通。后课快速幂离开图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>半流连通：存森林，插边若连接不同块则加。匹配：贪心边或更精的分层近似。计数三角形要抽样或多遍。输出常常是近似或随机正确。</p>',11)),(e(),l(p,null,{default:r(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STR%5B%22%E8%BE%B9%E6%B5%81%22%5D%20--%3E%20MEM%5B%22%E7%A9%BA%E9%97%B4%20%C3%95(n)%20%E5%8D%8A%E6%B5%81%22%5D%0A%20%20MEM%20--%3E%20FOR%5B%22%E6%A3%AE%E6%9E%97%20%2F%20%E5%8C%B9%E9%85%8D%E8%BF%91%E4%BC%BC%22%5D%0A%20%20STR%20--%3E%20SK%5B%22%E6%9B%B4%E5%B0%8F%EF%BC%9A%E7%B4%A0%E6%8F%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>下界：一通扫描难以精确 \\(s\\)–\\(t\\) 连通的某些变体，点名即可。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\tilde O(n)\\) 刚好放下树，故半流连通「像」动态插入。删边流要更多遍或随机。与 Misra–Gries 等项计数流（后课）不同：这里有顶点身份，空间至少与 \\(n\\) 有关。与 PRAM：并行是时间，流是空间。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部图流下界表。不把 MapReduce 当半流定义。后课默认：图若只能扫边，先问半流空间；精确最短路回随机访问模型。下一课快速幂与矩阵幂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半流 \\(\\tilde O(n)\\)：森林级结构可维护。</li><li>精确很多问题要随机访问；流上近似/多遍。</li><li>与在线竞争比模型不同。</li><li>出处：Muthukrishnan, 2005；图流与线性素描文献。</li></ul>',7))])}const T=n(c,[["render",m]]);export{g as __pageData,T as default};
